export interface Activity {
  id: string;
  name: string;
  description?: string;
  category: string;
  dailyGoal?: number;
  createdAt: number;
}

export interface DailyStatus {
  [date: string]: {
    [activityId: string]: boolean;
  };
}

export interface AppData {
  version: number;
  activities: Activity[];
  dailyStatus: DailyStatus;
}

import { AppData, Activity, DailyStatus } from '../types';

const STORAGE_KEY = 'pulseboard_data';
const CURRENT_VERSION = 1;

const DEFAULT_DATA: AppData = {
  version: CURRENT_VERSION,
  activities: [],
  dailyStatus: {},
};

export const storage = {
  save: (data: AppData) => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    } catch (error) {
      console.error('Failed to save to localStorage', error);
    }
  },

  load: (): AppData => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (!stored) return DEFAULT_DATA;

      const parsed = JSON.parse(stored);

      if (!parsed || typeof parsed !== 'object') {
        return DEFAULT_DATA;
      }

      // Versioning check
      if (parsed.version !== CURRENT_VERSION) {
        console.warn('Stored data version mismatch. Resetting to default.');
        return DEFAULT_DATA;
      }

      // Basic validation of required fields
      if (!Array.isArray(parsed.activities) || !parsed.dailyStatus) {
        return DEFAULT_DATA;
      }

      return parsed;
    } catch (error) {
      console.error('Failed to load from localStorage, returning defaults', error);
      return DEFAULT_DATA;
    }
  },

  // Helper to get status for a specific date
  getStatusForDate: (date: string): Record<string, boolean> => {
    const data = storage.load();
    return data.dailyStatus[date] || {};
  },

  // Helper to update status for a specific date and activity
  setStatus: (date: string, activityId: string, completed: boolean) => {
    const data = storage.load();
    if (!data.dailyStatus[date]) {
      data.dailyStatus[date] = {};
    }
    data.dailyStatus[date][activityId] = completed;
    storage.save(data);
  },
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { AppData, Activity } from '../types';
import { storage } from '../lib/storage';
import { format, addDays, subDays, parseISO } from 'date-fns';

interface PulseContextType {
  currentDate: Date;
  activities: Activity[];
  setActivities: React.Dispatch<React.SetStateAction<Activity[]>>;
  setCurrentDate: (date: Date) => void;
  toggleActivity: (activityId: string, completed: boolean) => void;
  isActivityCompleted: (activityId: string) => boolean;
  addActivity: (activity: Omit<Activity, 'id' | 'createdAt'>) => void;
  updateActivity: (id: string, activity: Partial<Activity>) => void;
  deleteActivity: (id: string) => void;
}

const PulseContext = createContext<PulseContextType | undefined>(undefined);

export const PulseProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activities, setActivities] = useState<Activity[]>([]);

  useEffect(() => {
    const data = storage.load();
    setActivities(data.activities);
  }, []);

  const toggleActivity = (activityId: string, completed: boolean) => {
    const dateStr = format(currentDate, 'yyyy-MM-dd');
    storage.setStatus(dateStr, activityId, completed);
  };

  const isActivityCompleted = (activityId: string) => {
    const dateStr = format(currentDate, 'yyyy-MM-dd');
    return storage.getStatusForDate(dateStr)[activityId] || false;
  };

  const addActivity = (activityData: Omit<Activity, 'id' | 'createdAt'>) => {
    const newActivity: Activity = {
      ...activityData,
      id: crypto.randomUUID(),
      createdAt: Date.now(),
    };
    const updated = [...activities, newActivity];
    setActivities(updated);

    const data = storage.load();
    storage.save({ ...data, activities: updated });
  };

  const updateActivity = (id: string, updates: Partial<Activity>) => {
    const updated = activities.map(a => a.id === id ? { ...a, ...updates } : a);
    setActivities(updated);

    const data = storage.load();
    storage.save({ ...data, activities: updated });
  };

  const deleteActivity = (id: string) => {
    const updated = activities.filter(a => a.id !== id);
    setActivities(updated);

    const data = storage.load();
    storage.save({ ...data, activities: updated });
  };

  return (
    <PulseContext.Provider value={{ 
      currentDate, 
      setCurrentDate, 
      activities, 
      setActivities, 
      toggleActivity, 
      isActivityCompleted, 
      addActivity, 
      updateActivity, 
      deleteActivity 
    }}>
      {children}
    </PulseContext.Provider>
  );
};

export const usePulse = () => {
  const context = useContext(PulseContext);
  if (!context) throw new Error('usePulse must be used within a PulseProvider');
  return context;
};

import React, { useState } from 'react';
import { usePulse } from '../context/PulseContext';
import { Activity } from '../types';
import { Plus, X, Save, Trash2 } from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  activityToEdit?: Activity | null;
}

export const ActivityModal: React.FC<Props> = ({ isOpen, onClose, activityToEdit }) => {
  const { addActivity, updateActivity } = usePulse();
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState('General');
  const [dailyGoal, setDailyGoal] = useState<number | undefined>(undefined);

  React.useEffect(() => {
    if (activityToEdit) {
      setName(activityToEdit.name);
      setDescription(activityToEdit.description || '');
      setCategory(activityToEdit.category);
      setDailyGoal(activityToEdit.dailyGoal);
    } else {
      setName('');
      setDescription('');
      setCategory('General');
      setDailyGoal(undefined);
    }
  }, [activityToEdit]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    if (activityToEdit) {
      updateActivity(activityToEdit.id, { name, description, category, dailyGoal });
    } else {
      addActivity({ name, description, category, dailyGoal });
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-stone-900/50 backdrop-blur-sm">
      <div className="bg-white dark:bg-stone-900 w-full max-w-md border border-stone-200 dark:border-stone-800 p-6 shadow-xl">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-serif text-stone-900 dark:text-stone-100">
            {activityToEdit ? 'Edit Activity' : 'New Activity'}
          </h2>
          <button onClick={onClose} className="p-1 hover:bg-stone-100 dark:hover:bg-stone-800 rounded-full transition-colors">
            <X size={20} className="text-stone-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-stone-500 mb-1">Name</label>
            <input 
              autoFocus
              value={name} 
              onChange={e => setName(e.target.value)} 
              className="w-full px-3 py-2 border border-stone-200 dark:border-stone-700 bg-transparent rounded-sm focus:ring-1 focus:ring-olive-600 outline-none dark:text-stone-200"
              placeholder="e.g., Morning Meditation"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-stone-500 mb-1">Description (optional)</label>
            <textarea 
              value={description} 
              onChange={e => setDescription(e.target.value)} 
              className="w-full px-3 py-2 border border-stone-200 dark:border-stone-700 bg-transparent rounded-sm focus:ring-1 focus:ring-olive-600 outline-none dark:text-stone-200"
              placeholder="Why is this important?"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-stone-500 mb-1">Category</label>
              <input 
                value={category} 
                onChange={e => setCategory(e.target.value)} 
                className="w-full px-3 py-2 border border-stone-200 dark:border-stone-700 bg-transparent rounded-sm focus:ring-1 focus:ring-olive-600 outline-none dark:text-stone-200"
                placeholder="e.g., Wellness"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-stone-500 mb-1">Daily Goal (optional)</label>
              <input 
                type="number"
                value={dailyGoal || ''} 
                onChange={e => setDailyGoal(parseInt(e.target.value) || undefined)} 
                className="w-full px-3 py-2 border border-stone-200 dark:border-stone-700 bg-transparent rounded-sm focus:ring-1 focus:ring-olive-600 outline-none dark:text-stone-200"
                placeholder="1"
              />
            </div>
          </div>
          <div className="flex justify-end gap-3 pt-4">
            <button 
              type="button" 
              onClick={onClose} 
              className="px-4 py-2 text-sm text-stone-600 dark:text-stone-400 hover:text-stone-900 dark:hover:text-stone-100"
            >
              Cancel
            </button>
            <button 
              type="submit" 
              className="px-4 py-2 text-sm bg-stone-900 dark:bg-stone-100 text-stone-100 dark:text-stone-900 rounded-sm hover:opacity-90 transition-opacity flex items-center gap-2"
            >
              <Save size={16} />
              Save Activity
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React from 'react';
import { usePulse } from '../context/PulseContext';
import { ChevronLeft, ChevronRight, Plus, Trash2, Edit2 } from 'lucide-react';
import { format, addDays, subDays, isToday, isAfter } from 'date-fns';
import { ActivityModal } from './ActivityModal';
import { useState } from 'react';
import { Activity } from '../types';

export const PulseBoard: React.FC = () => {
  const { 
    currentDate, 
    setCurrentDate, 
    activities, 
    toggleActivity, 
    isActivityCompleted, 
    deleteActivity 
  } = usePulse();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingActivity, setEditingActivity] = useState<Activity | null>(null);

  const openAddModal = () => {
    setEditingActivity(null);
    setIsModalOpen(true);
  };

  const openEditModal = (activity: Activity) => {
    setEditingActivity(activity);
    setIsModalOpen(true);
  };

  const handleToggle = (id: string) => {
    const currentlyCompleted = isActivityCompleted(id);
    // Prevent checking future dates
    if (!currentlyCompleted && isAfter(currentDate, new Date())) {
      return;
    }
    toggleActivity(id, !currentlyCompleted);
  };

  const completedCount = activities.filter(a => isActivityCompleted(a.id)).length;
  const progress = activities.length > 0 ? (completedCount / activities.length) * 100 : 0;

  return (
    <div className="min-h-screen bg-[#FDFCFB] dark:bg-[#1A1A1C] text-stone-900 dark:text-stone-100 transition-colors duration-300 flex justify-center p-4 sm:p-8">
      <div className="w-full max-w-xl">

        {/* Header */}
        <header className="flex flex-col gap-6 mb-12">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <button 
                onClick={() => setCurrentDate(subDays(currentDate, 1))}
                className="p-2 hover:bg-stone-200 dark:hover:bg-stone-800 rounded-full transition-colors"
                aria-label="Previous Day"
              >
                <ChevronLeft size={24} />
              </button>
              <h1 className="text-3xl font-serif font-medium">
                {format(currentDate, 'EEEE, MMMM do')}
                {isToday(currentDate) && <span className="ml-3 text-sm font-sans uppercase tracking-widest text-olive-600 opacity-70">Today</span>}
              </h1>
              <button 
                onClick={() => setCurrentDate(addDays(currentDate, 1))}
                className="p-2 hover:bg-stone-200 dark:hover:bg-stone-800 rounded-full transition-colors"
                aria-label="Next Day"
              >
                <ChevronRight size={24} />
              </button>
            </div>
            <button 
              onClick={openAddModal}
              className="p-2 bg-stone-900 dark:bg-stone-100 text-stone-100 dark:text-stone-900 rounded-full hover:opacity-90 transition-opacity"
              aria-label="Add Activity"
            >
              <Plus size={24} />
            </button>
          </div>

          {/* Pulse Meter */}
          <div className="space-y-2">
            <div className="flex justify-between text-xs font-medium text-stone-500 uppercase tracking-wider">
              <span>Daily Progress</span>
              <span>{Math.round(progress)}%</span>
            </div>
            <div className="h-1.5 w-full bg-stone-200 dark:bg-stone-800 rounded-full overflow-hidden">
              <div 
                className="h-full bg-olive-600 transition-all duration-500 ease-out"
                style={{ width: `${progress}%` }}
              />
            </div>
            <div className="flex justify-between text-xs text-stone-400">
              <span>{completedCount} completed</span>
              <span>{activities.length - completedCount} remaining</span>
            </div>
          </div>
        </header>

        {/* Activities List */}
        <main className="space-y-1">
          {activities.length === 0 ? (
            <div className="py-20 text-center space-y-4">
              <p className="text-stone-400 font-serif italic">No activities defined yet.</p>
              <button 
                onClick={openAddModal}
                className="text-sm text-olive-600 hover:underline underline-offset-4"
              >
                Start by adding your first activity
              </button>
            </div>
          ) : (
            <div className="divide-y divide-stone-200 dark:divide-stone-800">
              {activities.map(activity => (
                <div 
                  key={activity.id} 
                  className={`group flex items-center justify-between py-4 transition-opacity ${isActivityCompleted(activity.id) ? 'opacity-50' : 'opacity-100'}`}
                >
                  <div className="flex items-center gap-4 flex-1">
                    <button 
                      onClick={() => handleToggle(activity.id)}
                      className={`w-6 h-6 rounded-full border-2 transition-all flex items-center justify-center ${
                        isActivityCompleted(activity.id) 
                        ? 'bg-olive-600 border-olive-600 text-white' 
                        : 'border-stone-300 dark:border-stone-700 hover:border-olive-600'
                      }`}
                      aria-label="Toggle completion"
                    >
                      {isActivityCompleted(activity.id) && <span className="text-xs">✓</span>}
                    </button>
                    <div className="flex flex-col">
                      <span className={`text-lg transition-colors ${isActivityCompleted(activity.id) ? 'line-through text-stone-400' : ''}`}>
                        {activity.name}
                      </span>
                      {activity.description && (
                        <span className="text-xs text-stone-500 line-clamp-1">{activity.description}</span>
                      )}
                      <span className="text-[10px] uppercase tracking-tighter text-stone-400 mt-1">
                        {activity.category}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button 
                      onClick={() => openEditModal(activity)}
                      className="p-2 text-stone-400 hover:text-stone-900 dark:hover:text-stone-100 transition-colors"
                      aria-label="Edit"
                    >
                      <Edit2 size={16} />
                    </button>
                    <button 
                      onClick={() => {
                        if (confirm('Delete this activity?')) deleteActivity(activity.id);
                      }}
                      className="p-2 text-stone-400 hover:text-red-500 transition-colors"
                      aria-label="Delete"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </main>

        <ActivityModal 
          isOpen={isModalOpen} 
          onClose={() => setIsModalOpen(false)} 
          activityToEdit={editingActivity} 
        />
      </div>
    </div>
  );
};

import React from 'react';
